/* Standalone type/semantics harness for the ported guard (NOT a kernel build).
 * Mirrors the target declarations:
 *   struct brcmf_pno_net_info_le { u8 bssid[6]; u8 channel; u8 SSID_len; u8 SSID[32]; };
 *   struct cfg80211_ssid { u8 ssid[IEEE80211_MAX_SSID_LEN]; u8 ssid_len; };
 *   #define IEEE80211_MAX_SSID_LEN 32
 */
typedef unsigned char u8;
#define IEEE80211_MAX_SSID_LEN 32

struct brcmf_pno_net_info_le {
	u8 bssid[6];
	u8 channel;
	u8 SSID_len;
	u8 SSID[32];
};

struct cfg80211_ssid {
	u8 ssid[IEEE80211_MAX_SSID_LEN];
	u8 ssid_len;
};

void brcmf_wowl_nd_results_guard(struct cfg80211_ssid *dst,
				 struct brcmf_pno_net_info_le *netinfo)
{
	if (netinfo->SSID_len > IEEE80211_MAX_SSID_LEN)
		netinfo->SSID_len = IEEE80211_MAX_SSID_LEN;
	__builtin_memcpy(dst->ssid, netinfo->SSID, netinfo->SSID_len);
	dst->ssid_len = netinfo->SSID_len;
}
EOF
